Warehouses = Q.Execute().Select(QueryResultIteration.ByGroups);
while (Warehouses.Next()) {
    Items = Warehouses.Select();
    while (Items.Next()) {
        Message(String(Warehouses.Warehouse) + " / " + String(Items.Item));
    }
}

